	// here and must be left exactly as it was.
	if g.dn != nil {
		if err := g.dn.Speculate(on); err != nil {
			return err
		}
	}
	if g.ple != nil {
		if err := g.ple.Speculate(on); err != nil {
			if g.dn != nil {
