			return err
		}
	}
	if g.ple != nil {
		if err := g.ple.SetPast(g.past); err != nil {
			return err
		}
	}
	if g.dn != nil {
		if err := g.dn.SetPast(g.past); err != nil {
			return err
		}
	}
	g.specArmed, g.specBlocks = false, nil
	return nil
