func specLoop(sp *llm.Speculator, ids []int32, n int, eog map[int32]bool) (specRun, error) {
	first, err := sp.Start(ids)
	if err != nil {
		return specRun{}, err
	}
	defer sp.Stop()
	sp.ResetGraphStats()
	out := make([]int32, 0, n)
	out = append(out, first)
	t0 := time.Now()
	var buf []int32
	for len(out) < n && !eog[out[len(out)-1]] {
		buf, err = sp.Next(buf)
		if err != nil {
			return specRun{}, err
		}
		for _, id := range buf {
			out = append(out, id)
			if len(out) == n || eog[id] {
