func (g *DeltaNetGPU) winAt(layer, slot int) uint32 {
	return g.layers[layer].win + uint32(slot*g.winStride)
}

// stateDst is the slot the next pass writes: the live one in an ordinary
// pass, the other one while a speculative pass is in flight.
func (g *DeltaNetGPU) stateDst() int {
	if g.stateSpec {
		return 1 - g.stateSlot
	}
	return g.stateSlot
}

// Speculate makes the next passes rewindable: they read the committed slot of
// every layer's recurrent state and convolution ring and write the other one,
// so that discarding a pass is doing nothing at all (P5c). CommitSlot then
// makes what the pass wrote the committed slot, and nothing else does.
//
// It is off in decode and in prefill, where the pass *is* the commit — and it
// has to be, because the two slots are different push constants and P1c's
// pre-recorded decode step is the same bytes every token.
func (g *DeltaNetGPU) Speculate(on bool) error {
	if on && g.seqSlots {
		return fmt.Errorf("llm: this block's slots are sequences (GraphOpts.Slots); it cannot also speculate")
	}
	if on && g.slots < 2 {
		return fmt.Errorf("llm: this block was staged with one state slot; a rewindable pass needs two " +
			"(GraphOpts.Speculative)")
	}
	g.stateSpec = on
	return nil
}

func (g *DeltaNetGPU) Speculating() bool { return g.stateSpec }

// KeepFirst makes every speculative pass also leave its first row folded into
// the committed slot (P20c), which is what lets Graph.KeepFirst accept row 0
// of a pass without re-running it. A pass of more rows than the ring holds
// would not store row 0 in the ring at all, so the graph refuses those.
func (g *DeltaNetGPU) KeepFirst(on bool) { g.keepFirst = on }

// RingRows is the convolution's history length, the most rows a keep-first
// pass may carry.
func (g *DeltaNetGPU) RingRows() int { return g.cfg.Conv - 1 }

// CommitSlot accepts whatever the last speculative pass wrote.
func (g *DeltaNetGPU) CommitSlot() {
	if g.stateSpec {
		g.stateSlot = 1 - g.stateSlot
	}
}

// StateSlot is which of the two slots is committed, for a test that wants to
// see the ping-pong rather than infer it.
func (g *DeltaNetGPU) StateSlot() int { return g.stateSlot }

// CarriedLen is how many float32s one sequence carries through this block
// from pass to pass: every layer's recurrent state and convolution ring.
func (g *PLEGPU) histDst() int {
	if g.histSpec {
		return 1 - g.histSlot
	}
	return g.histSlot
}

// Speculate makes the next passes rewindable — they read the committed ring
// and write the other one — and CommitSlot accepts what one of them wrote.
// See DeltaNetGPU.Speculate: this block carries no recurrent state, so the
// nine-row ring is the whole of what it has to roll back.
func (g *PLEGPU) Speculate(on bool) error {
	if on && g.seqSlots {
		return fmt.Errorf("llm: this block's slots are sequences (GraphOpts.Slots); it cannot also speculate")
	}
	if on && g.slots < 2 {
		return fmt.Errorf("llm: this block was staged with one ring slot; a rewindable pass needs two " +
			"(GraphOpts.Speculative)")
	}
	g.histSpec = on
	return nil
}

// KeepFirst is DeltaNetGPU.KeepFirst for the ring (P20c).
func (g *PLEGPU) KeepFirst(on bool) { g.keepFirst = on }

// RingRows is the ring's length, the most rows a keep-first pass may carry.
func (g *PLEGPU) RingRows() int { return g.cfg.ConvHist() }

func (g *PLEGPU) CommitSlot() {
	if g.histSpec {
		g.histSlot = 1 - g.histSlot
	}
}

// UseSlot makes sequence slot s's ring the one every pass reads and writes

