		n += len(ids)
		fmt.Printf("counted %s: %d tokens\n", f, len(ids))
	}
	rank := make([]int32, vocab)
	for i := range rank {
		rank[i] = int32(i)
	}
	sort.SliceStable(rank, func(a, b int) bool { return count[rank[a]] > count[rank[b]] })
	seen := 0
	for _, c := range count {
		if c > 0 {
			seen++
		}
	}
	fmt.Printf("%d tokens counted, %d distinct of %d\n\n", n, seen, vocab)

	ks := []int{4096, 8192, 16384, 32768, 65536}
	for _, f := range strings.Split(*test, ",") {
		ids := enc(f)
		pos := make([]int, vocab)
		for i, id := range rank {
			pos[id] = i
		}
		fmt.Printf("%s, %d tokens: share inside the top K\n", f, len(ids))
		fmt.Printf("%8s %10s %10s\n", "K", "counted", "id order")
		for _, k := range ks {
			c, o := 0, 0
			for _, id := range ids {
				if pos[id] < k {
					c++
				}
				if int(id) < k {
					o++
				}
			}
			fmt.Printf("%8d %9.2f%% %9.2f%%\n", k, 100*float64(c)/float64(len(ids)), 100*float64(o)/float64(len(ids)))
		}
		fmt.Println()
	}
	if *out != "" {
		f, err := os.Create(*out)
		if err != nil {
			log.Fatal(err)
		}
		if err := binary.Write(f, binary.LittleEndian, rank); err != nil {
			log.Fatal(err)
		}
		if err := f.Close(); err != nil {
			log.Fatal(err)
		}
		fmt.Printf("wrote %s\n", *out)
	}
}
